const phone = msg.payload.phone;
const code = String(crypto.randomInt(0, 1000000)).padStart(6, '0');

// Keep it on the server, with an expiry, to compare with what the person types.
flow.set(`signin:${phone}`, { code, expires: Date.now() + 10 * 60 * 1000 });

msg.to = phone;
msg.payload = `Your sign-in code is ${code}. It expires in 10 minutes.`;
return msg;
